function icon(name,sz=''){return `<svg class="ico ${sz}" viewBox="0 0 24 24" aria-hidden="true">${ICON[name]||ICON.grid}</svg>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
