const LA_V5_BANK={"A1":{"grammar":[{"id":"A1-grammar-1","level":"A1","skill":"grammar","q":"Choose the sentence about a daily routine.","options":["She usually walk to work.","She usually walks to work.","She is usually walk to work.","She walking usually to work."],"answer":1,"explanation":"Third-person singular present simple takes -s: walks."},{"id":"A1-grammar-2","level":"A1","skill":"grammar","q":"“I ___ in Namangan, but my sister lives in Tashkent.”","options":["live","lives","living","am live"],"answer":0,"explanation":"I live: present simple with I."},{"id":"A1-grammar-3","level":"A1","skill":"grammar","q":"“We ___ the same English teacher.”","options":["has","have","are have","having"],"answer":1,"explanation":"We have: plural subject."},{"id":"A1-grammar-4","level":"A1","skill":"grammar","q":"“There ___ two notebooks on the desk.”","options":["is","has","are","be"],"answer":2,"explanation":"There are: plural noun notebooks."},{"id":"A1-grammar-5","level":"A1","skill":"grammar","q":"“He ___ breakfast before school every day.”","options":["have","having","has","had"],"answer":2,"explanation":"He has breakfast: regular habit."}],"vocabulary":[{"id":"A1-vocabulary-1","level":"A1","skill":"vocabulary","q":"Choose the opposite of “early”.","options":["soon","late","quickly","before"],"answer":1,"explanation":"Early and late contrast in time."},{"id":"A1-vocabulary-2","level":"A1","skill":"vocabulary","q":"“The glass is empty.” What is the opposite of “empty”?","options":["full","clean","clear","light"],"answer":0,"explanation":"Full is the antonym of empty."},{"id":"A1-vocabulary-3","level":"A1","skill":"vocabulary","q":"Which word completes “a ___ of shoes”?","options":["bunch","pair","crowd","collection"],"answer":1,"explanation":"A pair of shoes is the conventional expression."},{"id":"A1-vocabulary-4","level":"A1","skill":"vocabulary","q":"“I am thirsty.” What do I need?","options":["a meal","some water","a rest","a coat"],"answer":1,"explanation":"Thirsty describes the need for a drink."},{"id":"A1-vocabulary-5","level":"A1","skill":"vocabulary","q":"Which phrase means “not expensive”?","options":["on sale","low-priced","low-quality","second-hand"],"answer":1,"explanation":"Low-priced describes cost, not sales or condition."}],"reading":[{"id":"A1-reading-1","level":"A1","skill":"reading","q":"When does Ali finish work?","options":["At 8 a.m.","At 9 a.m.","At 5 p.m.","At 6 p.m."],"answer":2,"explanation":"The passage states that he goes home at five.","passage":"Ali works in a library. He arrives at eight forty-five, begins work at nine and goes home at five. His brother finishes at six."},{"id":"A1-reading-2","level":"A1","skill":"reading","q":"What does Sara eat for breakfast?","options":["Bread and milk","Eggs and tea","Bread and eggs","Rice and milk"],"answer":0,"explanation":"Sara has bread and milk.","passage":"Sara gets up at seven. She buys eggs for tomorrow but today she eats bread and drinks milk before walking to school."},{"id":"A1-reading-3","level":"A1","skill":"reading","q":"How does Tom usually travel to work?","options":["By bus","On foot","By bicycle","By car"],"answer":2,"explanation":"Tom usually cycles to work.","passage":"Tom owns a car and sometimes takes the bus, but he usually rides his bicycle to the office because it is nearby."},{"id":"A1-reading-4","level":"A1","skill":"reading","q":"When can you visit the shop?","options":["Sunday at 10 a.m.","Friday at 5 p.m.","Saturday at 7 p.m.","Monday at 7 a.m."],"answer":1,"explanation":"Friday at five falls during the stated opening hours.","passage":"The shop opens from eight in the morning to six in the evening, Monday to Saturday. It is closed all day Sunday."},{"id":"A1-reading-5","level":"A1","skill":"reading","q":"How many pets does Mina have altogether?","options":["Two","Three","Four","Five"],"answer":1,"explanation":"Two cats plus one dog equals three pets.","passage":"Mina has two cats, one white and one black, and a small brown dog. Her neighbour has a rabbit."}],"listening":[{"id":"A1-listening-1","level":"A1","skill":"listening","q":"What time will the train actually leave?","options":["7:45","8:05","8:15","8:30"],"answer":2,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Good morning. The train at seven forty-five has been cancelled. The next one leaves at eight fifteen. Please be on the platform by eight five."},{"id":"A1-listening-2","level":"A1","skill":"listening","q":"Which drink does the customer order?","options":["Coffee with milk","Tea without sugar","Tea with sugar","Orange juice"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Could I have tea, please? No, not coffee. Tea is fine, and please don’t put sugar in it."},{"id":"A1-listening-3","level":"A1","skill":"listening","q":"Where is the speaker going first?","options":["The pharmacy","The supermarket","The cinema","The park"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I’m going to the supermarket for bread. After that, I’ll walk through the park on my way home."},{"id":"A1-listening-4","level":"A1","skill":"listening","q":"How many museum tickets are needed?","options":["One","Two","Three","Four"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Two tickets, please. My sister is coming with me, but our parents have their tickets already."},{"id":"A1-listening-5","level":"A1","skill":"listening","q":"What colour is the speaker’s own bag?","options":["Black","Blue","Grey","Green"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"There’s a black bag by the window, but it isn’t mine. My bag is blue, on the chair."}],"use":[{"id":"A1-use-1","level":"A1","skill":"use","q":"At a café, you are ready to order. Which request is most appropriate?","options":["Could I have a tea, please?","Would you have a tea?","Do I get you a tea?","I should give you a tea."],"answer":0,"explanation":"Could I have …, please? is a natural polite request."},{"id":"A1-use-2","level":"A1","skill":"use","q":"Someone says “Sorry I am late.” Choose a suitable reply.","options":["I am fine, thanks.","No problem.","Congratulations.","You are welcome."],"answer":1,"explanation":"No problem responds naturally to a minor apology."},{"id":"A1-use-3","level":"A1","skill":"use","q":"You want to ask the time. Which question is correct?","options":["What time it is?","How is the time?","What time is it?","When time is it?"],"answer":2,"explanation":"Direct question requires is before it."},{"id":"A1-use-4","level":"A1","skill":"use","q":"You cannot hear your teacher. What should you say?","options":["May I speak again?","Could you say that again, please?","Should I repeat you?","Do you talk again?"],"answer":1,"explanation":"Polite repetition request: Could you say that again?"},{"id":"A1-use-5","level":"A1","skill":"use","q":"You meet a new classmate. Which response fits after “My name is Sam”?","options":["Very nice you.","Good knowing the name.","Nice to meet you, Sam.","I am meeting nicely."],"answer":2,"explanation":"Nice to meet you is a standard greeting."}]},"A2":{"grammar":[{"id":"A2-grammar-1","level":"A2","skill":"grammar","q":"“We ___ the exhibition last Saturday.”","options":["have visited","visited","were visiting","had visited"],"answer":1,"explanation":"Finished, dated past event: visited."},{"id":"A2-grammar-2","level":"A2","skill":"grammar","q":"“There isn’t ___ information on the poster.”","options":["many","a few","much","several"],"answer":2,"explanation":"Information is uncountable: much."},{"id":"A2-grammar-3","level":"A2","skill":"grammar","q":"“If the shop is closed, we ___ online.”","options":["order","will order","ordered","had ordered"],"answer":1,"explanation":"First conditional: if + present, will + base verb."},{"id":"A2-grammar-4","level":"A2","skill":"grammar","q":"“The new route is ___ than the old one.”","options":["more fast","faster","fastest","as fast"],"answer":1,"explanation":"Comparative form: faster than."},{"id":"A2-grammar-5","level":"A2","skill":"grammar","q":"“I have been at this school ___ September.”","options":["for","since","during","from"],"answer":1,"explanation":"Since introduces the starting time."}],"vocabulary":[{"id":"A2-vocabulary-1","level":"A2","skill":"vocabulary","q":"Which document shows you have already paid?","options":["invoice","receipt","estimate","application"],"answer":1,"explanation":"A receipt confirms payment; an invoice requests payment."},{"id":"A2-vocabulary-2","level":"A2","skill":"vocabulary","q":"The platform was “crowded” at noon. What does this mean?","options":["There was little space.","It was far away.","It was closed.","It was expensive."],"answer":0,"explanation":"Crowded: many people in one place."},{"id":"A2-vocabulary-3","level":"A2","skill":"vocabulary","q":"Which verb means to fix a broken device?","options":["replace","repair","return","renew"],"answer":1,"explanation":"Repair means fix; replace means use a different device."},{"id":"A2-vocabulary-4","level":"A2","skill":"vocabulary","q":"You “borrow” a laptop when you …","options":["buy it second-hand","keep it forever","use it temporarily with permission","give it to someone"],"answer":2,"explanation":"Borrow implies temporary use, usually with permission."},{"id":"A2-vocabulary-5","level":"A2","skill":"vocabulary","q":"Choose the natural English expression.","options":["make a photo","write a photo","take a photo","do a photo"],"answer":2,"explanation":"Take a photo is standard English."}],"reading":[{"id":"A2-reading-1","level":"A2","skill":"reading","q":"Why did Anna miss the bus?","options":["She forgot the route.","The bus was full.","Her alarm did not ring.","She went to the wrong stop."],"answer":2,"explanation":"Uning budilnigi ishlamagan.","passage":"Anna arrived late because her alarm did not ring. She missed the 8:10 bus and took the next one at 8:40."},{"id":"A2-reading-2","level":"A2","skill":"reading","q":"What is included in the museum ticket?","options":["A guided tour","A free lunch","A train journey","A souvenir"],"answer":0,"explanation":"Ticket includes a guided tour.","passage":"Entry to the museum costs ten pounds. The price includes a short guided tour, but food and drinks are extra."},{"id":"A2-reading-3","level":"A2","skill":"reading","q":"When should the form be sent?","options":["Before Friday","On Saturday","After the course","Next month"],"answer":0,"explanation":"“by Thursday evening” — juma kunidan oldin.","passage":"Please complete the application by Thursday evening. We will contact successful applicants on Monday."},{"id":"A2-reading-4","level":"A2","skill":"reading","q":"Why is the meeting online?","options":["The speaker is ill.","The office is being repaired.","There are too many people.","The teacher is abroad."],"answer":1,"explanation":"Ofis ta’mirlanayotgani uchun online.","passage":"We will meet online this week because the office is being repaired. The usual room will be available next Monday."},{"id":"A2-reading-5","level":"A2","skill":"reading","q":"What should guests bring?","options":["Their own towels","A printed ticket","A notebook","Warm clothes"],"answer":3,"explanation":"Tashqaridagi tadbir uchun warm clothes so‘ralgan.","passage":"The evening event is outside. Chairs and drinks are provided, but please bring warm clothes because it may get cold."}],"listening":[{"id":"A2-listening-1","level":"A2","skill":"listening","q":"When will the class start?","options":["10:00","10:15","10:30","11:00"],"answer":2,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"We usually begin at ten, but our teacher’s train is delayed. Today we will start half an hour later, at ten thirty."},{"id":"A2-listening-2","level":"A2","skill":"listening","q":"Where must visitors go before Room 12?","options":["Reception","Library","Café","Main hall"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Please don’t go straight to room twelve. Pick up your visitor card at reception first, then head upstairs."},{"id":"A2-listening-3","level":"A2","skill":"listening","q":"Which appointment does the caller request?","options":["Tuesday morning","Wednesday afternoon","Thursday afternoon","Friday morning"],"answer":2,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I’m booked for Tuesday morning. I have a meeting then. Could I move the appointment to Thursday afternoon?"},{"id":"A2-listening-4","level":"A2","skill":"listening","q":"What is the price for a student?","options":["£6","£8","£10","£12"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Adult tickets are twelve pounds. With a student card, it’s eight. Children pay six pounds."},{"id":"A2-listening-5","level":"A2","skill":"listening","q":"What did the speaker eventually buy?","options":["A coat","A jacket","A pair of shoes","A backpack"],"answer":2,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I went out for a jacket, and almost bought a coat instead, but I ended up getting shoes."}],"use":[{"id":"A2-use-1","level":"A2","skill":"use","q":"You need to reschedule a lesson. Which message is best?","options":["I will not arrive yesterday.","Could we move tomorrow’s lesson to Friday?","My lesson can be moving after.","Tomorrow we are not previous lesson."],"answer":1,"explanation":"Could we move …? is clear and polite."},{"id":"A2-use-2","level":"A2","skill":"use","q":"Your friend offers another slice of cake but you have eaten enough.","options":["Yes, very much.","Not any, I have.","No thanks, I’m full.","I don’t want never."],"answer":2,"explanation":"No thanks, I’m full is a natural polite refusal."},{"id":"A2-use-3","level":"A2","skill":"use","q":"A sign reads “Staff only”. What should visitors do?","options":["Wait for a staff member to invite them.","Go inside to ask for information.","Enter if the door is open.","Use the area when it is quiet."],"answer":0,"explanation":"Staff only restricts access to authorised staff."},{"id":"A2-use-4","level":"A2","skill":"use","q":"Which request is both polite and grammatically correct?","options":["Could you tell me where the station is?","Could you tell me where is the station?","Can you say where does the station stand?","Would you tell where the station is it?"],"answer":0,"explanation":"Embedded questions use statement word order."},{"id":"A2-use-5","level":"A2","skill":"use","q":"Complete naturally: “I’m looking forward ___ from you.”","options":["for hearing","to hear","to hearing","hearing"],"answer":2,"explanation":"Look forward to + -ing form."}]},"B1":{"grammar":[{"id":"B1-grammar-1","level":"B1","skill":"grammar","q":"I wish I ___ more time to study.","options":["have","had","will have","am having"],"answer":1,"explanation":"Hozirgi vaziyatga nisbatan wish + Past Simple."},{"id":"B1-grammar-2","level":"B1","skill":"grammar","q":"The report ___ before the meeting.","options":["finished","has finish","was finished","finishing"],"answer":2,"explanation":"Passive Past Simple: was finished."},{"id":"B1-grammar-3","level":"B1","skill":"grammar","q":"She asked me where I ___.","options":["lived","live","living","have live"],"answer":0,"explanation":"Reported question: she asked where I lived."},{"id":"B1-grammar-4","level":"B1","skill":"grammar","q":"You ___ wear a seat belt in a car.","options":["might","would","could","must"],"answer":3,"explanation":"Must — qat’iy majburiyat."},{"id":"B1-grammar-5","level":"B1","skill":"grammar","q":"By the time I arrived, they ___ dinner.","options":["have finished","had finished","finish","are finishing"],"answer":1,"explanation":"Oldin tugagan harakat: Past Perfect."}],"vocabulary":[{"id":"B1-vocabulary-1","level":"B1","skill":"vocabulary","q":"Which word best describes someone whose promises you can depend on?","options":["consistent","reliable","predictable","accurate"],"answer":1,"explanation":"Reliable refers to dependable behaviour; consistent means stable."},{"id":"B1-vocabulary-2","level":"B1","skill":"vocabulary","q":"Which expression most directly means selecting one of several options?","options":["reach an agreement","make a decision","take a risk","draw a conclusion"],"answer":1,"explanation":"Make a decision means to choose an option; the other expressions describe agreement, risk or inference."},{"id":"B1-vocabulary-3","level":"B1","skill":"vocabulary","q":"A deadline is the time by which a task …","options":["may begin","must be finished","is usually checked","can be postponed"],"answer":1,"explanation":"A deadline is the latest permitted completion time."},{"id":"B1-vocabulary-4","level":"B1","skill":"vocabulary","q":"“Reduce” is closest to ___.","options":["increase","repeat","remove","decrease"],"answer":3,"explanation":"Reduce — kamaytirmoq."},{"id":"B1-vocabulary-5","level":"B1","skill":"vocabulary","q":"“Put off” a meeting means to ___.","options":["attend it early","organise it","postpone it","cancel it permanently"],"answer":2,"explanation":"Put off — keyinga qoldirmoq."}],"reading":[{"id":"B1-reading-1","level":"B1","skill":"reading","q":"What is the writer’s main concern?","options":["The price of buses","The number of shops","The lack of evening services","The quality of roads"],"answer":2,"explanation":"Asosiy shikoyat — kechki transport cheklangan.","passage":"Public transport has improved during the day, but people who work late still struggle to get home. The last bus leaves before many evening shifts finish."},{"id":"B1-reading-2","level":"B1","skill":"reading","q":"Why did the company change its policy?","options":["To respond to employee feedback","To reduce holiday entitlement","To move abroad","To avoid customers"],"answer":0,"explanation":"Xodimlar so‘rovlariga javoban o‘zgartirilgan.","passage":"After a staff survey showed demand for flexibility, the company introduced two remote-working days each week. Managers will review the arrangement after three months."},{"id":"B1-reading-3","level":"B1","skill":"reading","q":"What does “this approach” refer to?","options":["Sending daily emails","Teaching through small projects","Buying more books","Removing assessments"],"answer":1,"explanation":"This approach — kichik loyihalar orqali o‘qitish.","passage":"Rather than memorising long lists of rules, students now complete short projects. Teachers believe this approach helps them use knowledge in realistic situations."},{"id":"B1-reading-4","level":"B1","skill":"reading","q":"Which statement is supported?","options":["The park will close permanently.","The park is currently free.","The new facilities are already open.","The park will add lighting next spring."],"answer":3,"explanation":"Yangi yoritish bahorda o‘rnatilishi aytilgan.","passage":"The council has approved plans to install lighting in the city park next spring. The playground will remain open during the work, although some paths may close temporarily."},{"id":"B1-reading-5","level":"B1","skill":"reading","q":"What can be inferred about the workshop?","options":["It is meant only for experts.","Participants will work alone.","Experience is not necessary.","It lasts several weeks."],"answer":2,"explanation":"“No previous experience is required” — yangi boshlovchilar ham qatnashadi.","passage":"This Saturday’s photography workshop is designed for curious beginners. Cameras can be borrowed, and no previous experience is required. Places are limited."}],"listening":[{"id":"B1-listening-1","level":"B1","skill":"listening","q":"Why did the workshop finish early?","options":["The presenter was unwell","A technical issue interrupted the session","Too few people registered","The venue was double-booked"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"We planned to continue until five. Attendance was good and the speaker felt fine, but the sound system stopped working, so we finished early."},{"id":"B1-listening-2","level":"B1","skill":"listening","q":"What is the woman’s main concern about the new timetable?","options":["Higher costs","Less flexibility","The venue","Longer lessons"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The revised timetable works for most people, but I’m worried it leaves those with part-time jobs little room to move classes around."},{"id":"B1-listening-3","level":"B1","skill":"listening","q":"What does the man decide to do?","options":["Cancel the booking","Ask for a refund","Keep the current booking","Change the booking date"],"answer":3,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I’d prefer not to cancel. Could you switch my booking from Friday to the following Monday?"},{"id":"B1-listening-4","level":"B1","skill":"listening","q":"Why does the tutor recommend the article?","options":["It has the shortest summary","It provides contrasting examples","It uses simple vocabulary","It has attractive illustrations"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The article is quite long, but its main advantage is that it compares two approaches side by side."},{"id":"B1-listening-5","level":"B1","skill":"listening","q":"What has improved since the last meeting?","options":["The budget","The team size","The response time","The scope"],"answer":2,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Funding hasn’t increased, and the team is the same size, but we now answer requests much faster."}],"use":[{"id":"B1-use-1","level":"B1","skill":"use","q":"You disagree politely in a team meeting. Choose the best response.","options":["I understand your point, but could we consider another option?","That is not right, and everybody knows it.","You should have thought before speaking.","Whatever, do as you like."],"answer":0,"explanation":"Acknowledging another view before a proposal keeps the tone professional."},{"id":"B1-use-2","level":"B1","skill":"use","q":"A colleague asks whether the report is ready. It is almost complete.","options":["It has ready nearly.","I’m just putting the finishing touches on it.","It finishes itself near.","It was just being finished tomorrow."],"answer":1,"explanation":"Putting the finishing touches on something = completing the last details."},{"id":"B1-use-3","level":"B1","skill":"use","q":"Complete: “I’ll let you know as soon as I ___ an answer.”","options":["will get","got","get","have got to"],"answer":2,"explanation":"After as soon as referring to the future, use present simple."},{"id":"B1-use-4","level":"B1","skill":"use","q":"Which opening fits a formal email requesting information?","options":["Hey, tell me quickly.","I demand an answer.","I am writing to enquire about the course.","You have to explain the course."],"answer":2,"explanation":"A neutral, clear request suits a formal email."},{"id":"B1-use-5","level":"B1","skill":"use","q":"Choose the most natural phrase: “We had to ___ the meeting until Monday.”","options":["take off","put off","set off","turn off"],"answer":1,"explanation":"Put off means postpone."}]},"B2":{"grammar":[{"id":"B2-grammar-1","level":"B2","skill":"grammar","q":"Hardly ___ the presentation begun when the alarm rang.","options":["had","has","did","was"],"answer":0,"explanation":"Hardly had + subject + past participle — inversiya."},{"id":"B2-grammar-2","level":"B2","skill":"grammar","q":"If she had left earlier, she ___ the train.","options":["will catch","would catch","would have caught","caught"],"answer":2,"explanation":"Third conditional: would have + V3."},{"id":"B2-grammar-3","level":"B2","skill":"grammar","q":"The proposal, ___ was submitted last week, has been approved.","options":["who","that","whose","which"],"answer":3,"explanation":"Non-defining relative clause bilan which."},{"id":"B2-grammar-4","level":"B2","skill":"grammar","q":"Not only ___ the plan succeed, but it also saved money.","options":["was","did","has","had"],"answer":1,"explanation":"Not only gap boshida bo‘lsa did + subject + verb inversiyasi."},{"id":"B2-grammar-5","level":"B2","skill":"grammar","q":"She ___ forgotten the appointment; she is always punctual.","options":["can’t have","must have","should","may not"],"answer":0,"explanation":"Can’t have + V3 — o‘tgan holat haqida kuchli inkor xulosasi."}],"vocabulary":[{"id":"B2-vocabulary-1","level":"B2","skill":"vocabulary","q":"“Mitigate” a risk means to ___.","options":["ignore it","increase it","reduce its impact","describe it"],"answer":2,"explanation":"Mitigate — salbiy ta’sirini kamaytirish."},{"id":"B2-vocabulary-2","level":"B2","skill":"vocabulary","q":"Which collocation is most natural?","options":["deeply concern about","deep concern about","strong concerned for","high concerning on"],"answer":1,"explanation":"Deep concern about — to‘g‘ri collocation."},{"id":"B2-vocabulary-3","level":"B2","skill":"vocabulary","q":"A “feasible” proposal is ___.","options":["controversial","expensive","ambiguous","practical and achievable"],"answer":3,"explanation":"Feasible — amalga oshirish mumkin."},{"id":"B2-vocabulary-4","level":"B2","skill":"vocabulary","q":"“Scrutinise” means ___.","options":["examine closely","celebrate loudly","delay deliberately","copy quickly"],"answer":0,"explanation":"Scrutinise — sinchiklab tekshirmoq."},{"id":"B2-vocabulary-5","level":"B2","skill":"vocabulary","q":"Choose the correct phrase.","options":["reach a compromise","do a compromise","make to compromise","perform a compromise"],"answer":0,"explanation":"Reach a compromise — murosaga kelmoq."}],"reading":[{"id":"B2-reading-1","level":"B2","skill":"reading","q":"What is the writer’s attitude toward remote work?","options":["Entirely negative","Unconditionally positive","Cautiously supportive","Completely neutral"],"answer":2,"explanation":"Yordam beradi, biroq cheklovlar mavjud.","passage":"Remote work can make employment accessible to more people, particularly those with lengthy commutes. Yet managers should not assume it suits every task: mentoring and collaborative design sometimes benefit from being together."},{"id":"B2-reading-2","level":"B2","skill":"reading","q":"What is the main implication?","options":["The pilot proved the system useless.","The results require broader testing.","All regions are identical.","The costs have disappeared."],"answer":1,"explanation":"Bir shahardagi muvaffaqiyatni hamma joyga tatbiq qilib bo‘lmaydi.","passage":"A pilot programme reduced waste by 18% in one city. However, the organisers warned that local recycling facilities differ considerably, so the outcome should not be extrapolated without further trials."},{"id":"B2-reading-3","level":"B2","skill":"reading","q":"What does “offset” mean in this context?","options":["Conceal","Measure","Prohibit","Compensate for"],"answer":3,"explanation":"Offset — salbiy xarajatni qoplash yoki kamaytirish.","passage":"The new equipment requires a substantial initial investment, but lower energy bills should offset these costs over several years."},{"id":"B2-reading-4","level":"B2","skill":"reading","q":"Which assumption is the writer challenging?","options":["More data always creates better decisions.","People need training.","Data can be useful.","Privacy matters."],"answer":0,"explanation":"Muallif faqat ma’lumot ko‘payishi yetarli emasligini aytadi.","passage":"Organisations often collect more and more data, assuming that quantity produces better decisions. In reality, unclear objectives and weak analysis can make extensive data sets surprisingly unhelpful."},{"id":"B2-reading-5","level":"B2","skill":"reading","q":"Why were the findings unexpected?","options":["They matched earlier models.","No data was collected.","A small group showed a stronger effect.","The experiment was cancelled."],"answer":2,"explanation":"Kichik guruhda kattaroq o‘zgarish kuzatilgan.","passage":"Researchers expected the intervention to benefit larger classes most. Instead, the strongest improvement appeared in groups of fewer than twelve learners, prompting a closer examination of teacher feedback."}],"listening":[{"id":"B2-listening-1","level":"B2","skill":"listening","q":"What is the speaker’s main reservation?","options":["The timeline may be unrealistic","The goals are irrelevant","The costs were not calculated","The stakeholders have withdrawn"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The aims are sensible and the funding is secured. My concern is how much we expect to achieve before December."},{"id":"B2-listening-2","level":"B2","skill":"listening","q":"Which change was made to the research design?","options":["The control group was dropped","A follow-up phase was added","The sample was reduced","The questionnaire was shortened"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"We kept the same sample and control group but added interviews three months later to see whether the effects lasted."},{"id":"B2-listening-3","level":"B2","skill":"listening","q":"Why does the speaker favour the second proposal?","options":["It is cheaper upfront","It addresses the underlying cause","It needs fewer staff","It has more publicity"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The first proposal would give visible results quickly, but the second tackles why the problem keeps returning."},{"id":"B2-listening-4","level":"B2","skill":"listening","q":"What can be inferred about the feedback?","options":["It was unanimously favourable","It was mixed but useful","It did not address the project","It was ignored entirely"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"Several people praised the new format, while others found it confusing. We’ve used both sets of comments to revise it."},{"id":"B2-listening-5","level":"B2","skill":"listening","q":"What does the man imply about the deadline?","options":["The deadline is fixed","A short extension may be possible","The deadline has passed","No deadline was set"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The date is officially Friday, though if there’s a genuine problem we might be able to allow another day or two."}],"use":[{"id":"B2-use-1","level":"B2","skill":"use","q":"Which sentence expresses a cautious inference?","options":["He might have misunderstood the instructions.","He had to misunderstand the instructions.","He must not misunderstood the instructions.","He will have misunderstand the instructions."],"answer":0,"explanation":"Might have + past participle expresses uncertain past inference."},{"id":"B2-use-2","level":"B2","skill":"use","q":"Choose the strongest but fair concession.","options":["Although the cost is high, the long-term benefits may justify it.","The cost is high, so any benefit is impossible.","The cost is high, and every benefit is certain.","The cost is high because it is high."],"answer":0,"explanation":"Concession acknowledges cost while preserving measured claim."},{"id":"B2-use-3","level":"B2","skill":"use","q":"Which link expresses an unexpected contrast?","options":["Consequently","Moreover","Nevertheless","For instance"],"answer":2,"explanation":"Nevertheless indicates that a result holds despite the preceding argument."},{"id":"B2-use-4","level":"B2","skill":"use","q":"Complete: “The proposal was rejected ___ insufficient evidence.”","options":["due to","owing that","because of that","since of"],"answer":0,"explanation":"Due to + noun phrase is idiomatic."},{"id":"B2-use-5","level":"B2","skill":"use","q":"Which is the most natural academic phrasing?","options":["conduct research into consumer behaviour","make research at consumer behaviour","implement researches on consumers","produce researching about consumers"],"answer":0,"explanation":"Conduct research into is an established academic collocation."}]},"C1":{"grammar":[{"id":"C1-grammar-1","level":"C1","skill":"grammar","q":"Rarely ___ such a nuanced analysis in a public debate.","options":["we encounter","do we encounter","we do encounter","are we encounter"],"answer":1,"explanation":"Rarely boshida inversiya: do we encounter."},{"id":"C1-grammar-2","level":"C1","skill":"grammar","q":"Had the findings been replicated, the claim ___ stronger.","options":["is","will be","would have been","was"],"answer":2,"explanation":"Formal inverted third conditional: would have been."},{"id":"C1-grammar-3","level":"C1","skill":"grammar","q":"The committee insisted that the report ___ published in full.","options":["be","is","was","being"],"answer":0,"explanation":"Mandative subjunctive: insist that + base form."},{"id":"C1-grammar-4","level":"C1","skill":"grammar","q":"It was not until the trial ended ___ the anomaly became apparent.","options":["which","where","when","that"],"answer":3,"explanation":"Cleft construction: not until ... that."},{"id":"C1-grammar-5","level":"C1","skill":"grammar","q":"She spoke as though she ___ the decision herself.","options":["makes","had made","will make","was make"],"answer":1,"explanation":"Unreal past reference: as though + Past Perfect."}],"vocabulary":[{"id":"C1-vocabulary-1","level":"C1","skill":"vocabulary","q":"“Equivocal” evidence is ___.","options":["overwhelming","irrelevant","open to multiple interpretations","deliberately false"],"answer":2,"explanation":"Equivocal — bir ma’noli bo‘lmagan."},{"id":"C1-vocabulary-2","level":"C1","skill":"vocabulary","q":"“Inadvertently” most nearly means ___.","options":["unintentionally","confidently","repeatedly","strategically"],"answer":0,"explanation":"Inadvertently — bilmasdan, tasodifan."},{"id":"C1-vocabulary-3","level":"C1","skill":"vocabulary","q":"A “salient” feature is ___.","options":["outdated","minor","invisible","particularly noticeable or important"],"answer":3,"explanation":"Salient — eng muhim yoki ko‘zga tashlanadigan."},{"id":"C1-vocabulary-4","level":"C1","skill":"vocabulary","q":"“Exacerbate” a problem means to ___.","options":["investigate it","make it worse","solve it indirectly","explain it"],"answer":1,"explanation":"Exacerbate — muammoni kuchaytirmoq."},{"id":"C1-vocabulary-5","level":"C1","skill":"vocabulary","q":"Which collocation is standard?","options":["bear the consequences","carry on consequences","make consequences","take up consequences"],"answer":0,"explanation":"Bear the consequences — oqibatlarga duch kelmoq."}],"reading":[{"id":"C1-reading-1","level":"C1","skill":"reading","q":"What rhetorical strategy does the author use?","options":["Dismissal of all objections","Appeal to popularity","Concession followed by qualification","An unrelated anecdote"],"answer":2,"explanation":"Avval afzallikni tan oladi, keyin cheklovni ko‘rsatadi.","passage":"The intervention undeniably improved short-term engagement. Nevertheless, treating engagement as a proxy for sustained learning risks overlooking whether participants retain and transfer the knowledge months later."},{"id":"C1-reading-2","level":"C1","skill":"reading","q":"Which inference is best supported?","options":["The data are deliberately falsified.","The analysis may mask internal differences.","The intervention had no benefits.","All participants improved equally."],"answer":1,"explanation":"O‘rtacha ko‘rsatkich subguruhlar farqini yashirishi mumkin.","passage":"Although the aggregate figures suggest modest gains, separating participants by prior experience reveals two sharply contrasting trajectories. The overall average therefore tells only part of the story."},{"id":"C1-reading-3","level":"C1","skill":"reading","q":"What does “contingent” mean here?","options":["Permanent","Unexpected","Unethical","Dependent on conditions"],"answer":3,"explanation":"Contingent on — shartlarga bog‘liq.","passage":"The success of the initiative is contingent on sustained funding and the cooperation of regional agencies, neither of which has yet been secured."},{"id":"C1-reading-4","level":"C1","skill":"reading","q":"What is the author criticising?","options":["An oversimplified causal explanation","The existence of demographic data","The value of follow-up studies","The need for measurable outcomes"],"answer":0,"explanation":"Bir sababga haddan ziyod katta rol berilishi tanqid qilinadi.","passage":"Attributing the decline entirely to digital media is appealingly simple, but it ignores economic pressures, changes in curriculum and the possibility that several factors interact."},{"id":"C1-reading-5","level":"C1","skill":"reading","q":"What does the final sentence suggest?","options":["The project has been abandoned.","The approach was copied exactly.","The team adapted its strategy in response to limitations.","The results were fabricated."],"answer":2,"explanation":"Cheklovlar tan olinib, yondashuv o‘zgartirilgan.","passage":"The original framework assumed that all communities had access to similar infrastructure. Once this assumption proved untenable, the researchers redesigned the intervention rather than forcing local conditions into a uniform model."}],"listening":[{"id":"C1-listening-1","level":"C1","skill":"listening","q":"What qualification does the speaker make?","options":["The reform may work only in some contexts","The reform is universally beneficial","Implementation is irrelevant","The overall direction is wrong"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I support the reform in principle, but outcomes will depend on local capacity. It would be a mistake to expect the same results everywhere."},{"id":"C1-listening-2","level":"C1","skill":"listening","q":"Why is the follow-up study mentioned?","options":["It replicated the original effect exactly","It found a smaller effect, challenging the first estimate","It used unrelated participants","It rejected the topic entirely"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The first study found a large improvement. The bigger follow-up, however, detected a smaller effect and wider uncertainty."},{"id":"C1-listening-3","level":"C1","skill":"listening","q":"What attitude is conveyed?","options":["Cautious optimism","Unreserved enthusiasm","Firm rejection","Personal hostility"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"This is encouraging, but I would not call it a breakthrough until an independent team can reproduce the findings."},{"id":"C1-listening-4","level":"C1","skill":"listening","q":"What is implied about the public summary?","options":["It is more detailed than the appendix","It omits an important methodological caveat","It reports exactly the same uncertainty","It directly challenges the study"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The technical appendix shows overlapping confidence intervals. That detail, rather conveniently, is absent from the executive summary."},{"id":"C1-listening-5","level":"C1","skill":"listening","q":"Why does the speaker withhold judgement?","options":["The study lacks sufficient follow-up evidence","The study has been withdrawn","The funding has ended","The method was never documented"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The early signals look promising, yet the observation window is short. I’d prefer to see longer-term data before taking a firm position."}],"use":[{"id":"C1-use-1","level":"C1","skill":"use","q":"Which claim is most carefully qualified?","options":["The policy is guaranteed to improve outcomes.","The findings suggest an association, although causation remains unproven.","The policy works in every situation.","The evidence has eliminated all uncertainty."],"answer":1,"explanation":"Suggest and remains unproven express academically appropriate caution."},{"id":"C1-use-2","level":"C1","skill":"use","q":"Choose the transition that signals a consequence of the policy change.","options":["Nevertheless","Consequently","By contrast","For example"],"answer":1,"explanation":"Consequently signals a result, not contrast or illustration."},{"id":"C1-use-3","level":"C1","skill":"use","q":"Which phrase introduces a measured objection?","options":["There are compelling reasons to question the representativeness of the sample.","The sample is obviously worthless to everyone.","It is impossible to believe any numbers.","Only fools would accept this evidence."],"answer":0,"explanation":"Measured criticism identifies the specific weakness."},{"id":"C1-use-4","level":"C1","skill":"use","q":"Complete: “The author draws a distinction ___ correlation and causation.”","options":["among","about","between","on"],"answer":2,"explanation":"Draw a distinction between two concepts."},{"id":"C1-use-5","level":"C1","skill":"use","q":"Complete: “The findings must be interpreted ___ the small sample size.”","options":["in light of","on behalf of","at odds with","by dint of"],"answer":0,"explanation":"In light of introduces a relevant consideration."}]},"C2":{"grammar":[{"id":"C2-grammar-1","level":"C2","skill":"grammar","q":"No sooner ___ the announcement been made than speculation intensified.","options":["has","was","had","did"],"answer":2,"explanation":"No sooner had + subject + V3 than..."},{"id":"C2-grammar-2","level":"C2","skill":"grammar","q":"Were it not for the preliminary data, the hypothesis ___ untenable.","options":["would remain","will remain","had remained","remains"],"answer":0,"explanation":"Were it not for — formal unreal conditional."},{"id":"C2-grammar-3","level":"C2","skill":"grammar","q":"He demanded that the allegation ___ independently verified.","options":["is","was","being","be"],"answer":3,"explanation":"Subjunctive passive: be verified."},{"id":"C2-grammar-4","level":"C2","skill":"grammar","q":"Such ___ the intensity of the debate that proceedings were suspended.","options":["were","was","has","did"],"answer":1,"explanation":"Such was the intensity ... that — formal inversion."},{"id":"C2-grammar-5","level":"C2","skill":"grammar","q":"The report is all the more compelling ___ its limitations are candidly acknowledged.","options":["unless","whereas","because","despite"],"answer":2,"explanation":"Because qo‘shimcha asos keltiradi; all the more compelling because..."}],"vocabulary":[{"id":"C2-vocabulary-1","level":"C2","skill":"vocabulary","q":"“Perspicacious” most nearly means ___.","options":["astute and perceptive","fiercely impatient","deliberately vague","emotionally detached"],"answer":0,"explanation":"Perspicacious — teran fahmli."},{"id":"C2-vocabulary-2","level":"C2","skill":"vocabulary","q":"“Obfuscate” an argument means to ___.","options":["refute it","summarise it","strengthen it","make it less clear"],"answer":3,"explanation":"Obfuscate — ma’noni xiralashtirmoq."},{"id":"C2-vocabulary-3","level":"C2","skill":"vocabulary","q":"A “pyrrhic victory” is ___.","options":["a decisive effortless success","a win gained at excessive cost","a victory in sport","a victory by chance"],"answer":1,"explanation":"Pyrrhic victory — juda katta evaziga erishilgan g‘alaba."},{"id":"C2-vocabulary-4","level":"C2","skill":"vocabulary","q":"“Inchoate” refers to something ___.","options":["fully mature","deliberately deceptive","not yet fully formed","no longer relevant"],"answer":2,"explanation":"Inchoate — hali to‘liq shakllanmagan."},{"id":"C2-vocabulary-5","level":"C2","skill":"vocabulary","q":"To “prevaricate” is to ___.","options":["evade the truth or speak evasively","state facts precisely","openly apologise","reach agreement immediately"],"answer":0,"explanation":"Prevaricate — haqiqatdan qochib, mujmal gapirmoq."}],"reading":[{"id":"C2-reading-1","level":"C2","skill":"reading","q":"Which underlying critique is implied?","options":["All quantification is invalid.","Individual judgement is irrelevant.","Metrics are always deliberately manipulated.","A measurement framework can distort the phenomenon it purports to capture."],"answer":3,"explanation":"O‘lchov tizimi o‘zi baholayotgan hodisani o‘zgartirib yuborishi mumkin.","passage":"Once departments were ranked by the volume of completed cases, staff began prioritising quick resolutions. The reported efficiency gains were real in a narrow sense, but the more complex cases accumulated out of view."},{"id":"C2-reading-2","level":"C2","skill":"reading","q":"What is the author’s central paradox?","options":["Open standards always fail.","Safeguards designed to improve fairness may introduce new inequities.","Every reform has identical outcomes.","Private data have no value."],"answer":1,"explanation":"Adolatni oshirish uchun qilingan choralar yangi tengsizlik yaratishi mumkin.","passage":"The revised admissions rules sought to eliminate subjective judgement. Yet by assigning rigid scores to extracurricular activities, they inadvertently advantaged applicants who could afford extensive private coaching."},{"id":"C2-reading-3","level":"C2","skill":"reading","q":"What does the tone most strongly suggest?","options":["Unrestrained admiration","Outright contempt","Qualified irony","Personal resentment"],"answer":2,"explanation":"“Impressive, if one disregards...” — kinoyali cheklov.","passage":"The proposal is impressively comprehensive—provided one disregards the minor inconvenience that it offers no plausible account of how its central commitments might be funded."},{"id":"C2-reading-4","level":"C2","skill":"reading","q":"What assumption is being exposed?","options":["That correlation necessarily entails causation","That numerical comparisons are useful","That institutions collect data","That funding can affect outcomes"],"answer":0,"explanation":"Muallif korrelyatsiyadan sababiyat chiqarishni savol ostiga qo‘yadi.","passage":"A correlation between screen time and lower scores was presented as evidence of harm. Yet the analysis did not examine whether existing academic difficulties might themselves lead students to spend more time online."},{"id":"C2-reading-5","level":"C2","skill":"reading","q":"What is most strongly implied about the consensus?","options":["It emerged from exhaustive independent debate.","It has been formally rejected.","It is supported by every dataset.","It may reflect institutional pressures rather than genuine agreement."],"answer":3,"explanation":"Konsensus tashkiliy bosim natijasi bo‘lishi ehtimoli bor.","passage":"The report describes an unprecedented consensus, although dissenting reviewers were excluded from the final committee and several participating organisations had contractual reasons to endorse the outcome."}],"listening":[{"id":"C2-listening-1","level":"C2","skill":"listening","q":"What rhetorical strategy does the speaker use?","options":["Concede the aim but question a hidden premise","Dismiss the proposal through ridicule","Appeal only to tradition","Shift to an unrelated issue"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The ambition is admirable, and I do not dispute its merits. It does, however, presuppose the institutional capacity it purports to create."},{"id":"C2-listening-2","level":"C2","skill":"listening","q":"What is implied by the reference to decimal points?","options":["The projection has been audited","The precision is not justified by its assumptions","The uncertainty is negligible","The methodology is unusually robust"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The projected savings are stated to the nearest decimal point. Given how speculative the assumptions are, the precision strikes me as theatrical."},{"id":"C2-listening-3","level":"C2","skill":"listening","q":"What tension is highlighted?","options":["Full disclosure can undermine confidential participation","Transparency always prevents participation","Confidentiality makes accountability impossible","Public accountability has already been achieved"],"answer":0,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"We promise transparent governance, but publishing raw submissions would betray the trust of confidential contributors. Disclosure and accountability are not always identical."},{"id":"C2-listening-4","level":"C2","skill":"listening","q":"Why does the speaker resist calling the pilot a failure?","options":["Targets were fully achieved","It revealed useful structural constraints","It was never implemented","It generated an immediate financial surplus"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"I wouldn’t call the pilot a failure. It missed its targets, yes, yet it exposed bottlenecks the design team could not otherwise have seen."},{"id":"C2-listening-5","level":"C2","skill":"listening","q":"What does “conveniently” imply about the summary?","options":["It was efficiently written","It may have selected evidence favouring its claim","It was written for a general audience","It included every relevant indicator"],"answer":1,"explanation":"Audio yozuvdagi asosiy ma’lumot, taqqoslash yoki tuzatish javobni aniqlaydi.","audio":"The summary mentions the three measures that improved. Conveniently, it says nothing about the two indicators that worsened."}],"use":[{"id":"C2-use-1","level":"C2","skill":"use","q":"Which version makes a subtle reservation without outright dismissal?","options":["The thesis is misguided in every respect.","The thesis has merit, though its underlying assumptions warrant scrutiny.","The thesis is beyond further examination.","The thesis is unlikely because it is complicated."],"answer":1,"explanation":"The concessive structure retains merit while questioning premises."},{"id":"C2-use-2","level":"C2","skill":"use","q":"“The arrangement was a ___ solution, intended to bridge the gap until the full system was ready.”","options":["far-reaching","stopgap","sweeping","definitive"],"answer":1,"explanation":"Stopgap specifically means a temporary expedient until a lasting solution exists."},{"id":"C2-use-3","level":"C2","skill":"use","q":"Which expression most naturally concedes a point before refocusing the argument?","options":["Be that as it may, the central question remains unresolved.","Insofar meanwhile, the central question remains.","Albeit hence, the matter has resolved.","Although nevertheless, the central question remains."],"answer":0,"explanation":"Be that as it may is a concessive idiom."},{"id":"C2-use-4","level":"C2","skill":"use","q":"Which formulation is the most precise about an uncertain finding?","options":["The approach changed many things significantly.","The initiative was evidently very helpful.","The intervention was associated with a small, statistically detectable improvement.","The experiment conclusively established universal effectiveness."],"answer":2,"explanation":"It distinguishes association from proof and specifies effect magnitude."},{"id":"C2-use-5","level":"C2","skill":"use","q":"Choose the sentence with standard formal “notwithstanding” usage.","options":["Notwithstanding of the delay, the review continued.","Notwithstanding the delay, the review continued.","Notwithstanding although the delay, the review continued.","Notwithstanding to the delay, the review continued."],"answer":1,"explanation":"Notwithstanding can function as a preposition without of."}]}};
/* All diagnostic data remains local to this standalone demonstration. */
const LA_V5_SKILLS=[['grammar','Grammar','Grammatika'],['vocabulary','Vocabulary','So‘z boyligi'],['reading','Reading','Matnni tushunish'],['listening','Listening','Eshitib tushunish'],['use','Use of English','Kontekst va nutq']];
const LA_V5_LEVELS=['A1','A2','B1','B2','C1','C2'];
const LA_V5_LEVEL_NAMES={A1:'Starter',A2:'Elementary',B1:'Intermediate',B2:'Upper intermediate',C1:'Advanced',C2:'Proficiency'};
const laV5State={mode:'select',level:'B1',items:[],answers:[],index:0,goal:'7.0',startedAt:0};
let laV5Speech=null,laV5Audio=null,laV5AudioUrls=new Map();
const laV5Safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function laV5Rand(n){const c=globalThis.crypto;if(c&&c.getRandomValues){const b=new Uint32Array(1);c.getRandomValues(b);return b[0]%n}return Math.floor(Math.random()*n)}
function laV5Shuffle(list){const a=list.slice();for(let i=a.length-1;i>0;i--){const j=laV5Rand(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function laV5MakeSet(level){const groups=Object.fromEntries(LA_V5_SKILLS.map(([key])=>[key,laV5Shuffle(LA_V5_BANK[level][key]).slice(0,3)]));const selected=[];for(let pass=0;pass<3;pass++){for(const skill of laV5Shuffle(LA_V5_SKILLS.map(s=>s[0]))){const q=groups[skill][pass];selected.push({...q,choices:laV5Shuffle(q.options.map((text,index)=>({text,correct:index===q.answer})))})}}return selected}
function laV5Percent(n,d){return Math.round(n*100/(d||1))}
function laV5Selected(){return laV5State.items[laV5State.index]}
function laV5ResultLabel(score){
 const l=laV5State.level,index=LA_V5_LEVELS.indexOf(l),en=landingLocale()==='en';
 if(score>=13)return en?
 {label:`${l}: strong performance`,note:`You performed well on this ${l} sample. Try the next level separately. This is not a certificate for ${LA_V5_LEVELS[index+1]||'C2+'}.`}:
 {label:`${l} mezonlarida yuqori natija`,note:`${l} darajasidagi ushbu namunani yaxshi bajardingiz. Yuqoriroq darajani alohida sinab ko‘ring. Bu avtomatik ${LA_V5_LEVELS[index+1]||'C2+'} sertifikati emas.`};
 if(score>=10)return en?
 {label:`Approaching ${l}`,note:`Your ${l} skills are promising, but not yet consistent across all areas. Review your errors.`}:
 {label:`${l} mezonlariga yaqin`,note:`${l} bo‘yicha ko‘nikmalaringiz yaxshi, lekin barcha yo‘nalishlar barqaror emas. Xatolarni qayta ko‘ring.`};
 if(score>=7)return en?
 {label:`Borderline ${l}`,note:`This sample does not provide enough evidence to confirm ${l}. Retake this level or try the level below.`}:
 {label:`${l} chegarasida`,note:`${l} darajasi bo‘yicha ishonchli xulosa uchun dalil yetarli emas. Shu darajani qayta ishlang yoki bir pog‘ona pastni sinang.`};
 return en?
 {label:`More preparation needed for ${l}`,note:`These questions were challenging. Consider starting with ${LA_V5_LEVELS[Math.max(0,index-1)]}.`}:
 {label:`${l} uchun qo‘shimcha tayyorgarlik zarur`,note:`Bu savollar siz uchun murakkab bo‘ldi. ${LA_V5_LEVELS[Math.max(0,index-1)]} sinovidan boshlash foydaliroq bo‘lishi mumkin.`};
}
function laV5View(){if(laV5State.mode==='select'){return `<div class="diag-head"><span class="diag-brand">✦ LEARNERS AREA / LEVEL CHECK</span><span class="diag-num">1 / 3 · Darajani tanlang</span></div><div class="diag-body"><div class="diag-eyebrow">START WITH YOUR OWN LEVEL</div><h3>Qaysi darajani <em>sinamoqchisiz?</em></h3><p class="diag-muted">Darajangizni oldindan belgilang. Test shu bosqichdagi real vazifalardan tuziladi va har safar aralashadi.</p><div class="diag-levels" role="group" aria-label="Ingliz tili darajasi">${LA_V5_LEVELS.map(l=>`<button type="button" class="diag-level ${laV5State.level===l?'active':''}" data-v5-level="${l}" aria-pressed="${laV5State.level===l}"><strong>${l}</strong><small>${LA_V5_LEVEL_NAMES[l]}</small></button>`).join('')}</div><div class="diag-preview"><span class="diag-info-dot">i</span><div><strong>15 savol · 5 ko‘nikma · ≈10–15 daqiqa</strong><small>Grammar, Vocabulary, Reading, Listening va Use of English — har biridan 3 tadan. Ro‘yxatdan o‘tmasdan ishlaydi.</small></div></div><div class="diag-footer"><span>Natija: tanlangan darajadagi ko‘rsatkich, xatolar va keyingi qadam.</span><button class="diag-primary" type="button" data-v5-start>15 savolli testni boshlash <span>↗</span></button></div></div>`}
if(laV5State.mode==='quiz'){
 const q=laV5Selected(),choice=laV5State.answers[laV5State.index],done=laV5State.answers.filter(x=>Number.isInteger(x)).length,sk=LA_V5_SKILLS.find(a=>a[0]===q.skill);const passage=q.skill==='reading'?`<div class="diag-reading"><span class="diag-block-tag">READING PASSAGE</span><p>${laV5Safe(q.passage)}</p></div>`:'';
 const audio=q.skill==='listening'?`<div class="diag-listening"><div class="diag-audio-ident"><span class="diag-audio-play-icon">♫</span><div><strong>Listening recording</strong><small>Matn natija chiqmaguncha yashiriladi. Bir necha marta tinglashingiz mumkin.</small></div></div><div class="diag-audio-tools"><button type="button" class="diag-audio-btn" data-v5-play>▶ Tinglash</button><button type="button" class="diag-audio-btn outline" data-v5-stop>Ⅱ</button><label class="diag-audio-upload">MP3 ulash <input type="file" accept="audio/mpeg,audio/mp3,audio/wav,audio/ogg,audio/mp4,audio/*" data-v5-upload hidden></label></div><small class="diag-audio-note" id="diag-audio-note">O‘zingizda mos yozuv bo‘lsa ulashingiz mumkin. Aks holda qurilma ovozi ishlatiladi.</small></div>`:'';
 return `<div class="diag-head"><span class="diag-brand">✦ DIAGNOSTIC / ${laV5Safe(laV5State.level)}</span><span class="diag-num">${laV5State.index+1} / 15</span></div><div class="diag-body"><div class="diag-test-meta"><span class="diag-eyebrow">${laV5Safe(sk[1])} · ${laV5Safe(laV5State.level)}</span><span>${landingLocale()==='en'?`${done} answers selected`:`${done} ta javob belgilangan`}</span></div><div class="diag-tracker" aria-label="15 savol progressi">${laV5State.items.map((x,i)=>`<button type="button" data-v5-jump="${i}" title="${i+1}-savol" aria-label="${i+1}-savol" class="${i===laV5State.index?'now':Number.isInteger(laV5State.answers[i])?'answered':''}"></button>`).join('')}</div>${passage}${audio}<h3 class="diag-question">${laV5Safe(q.q)}</h3><div class="diag-options" role="group" aria-label="Javob variantlari">${q.choices.map((op,i)=>`<button type="button" class="diag-option ${choice===i?'picked':''}" aria-pressed="${choice===i}" data-v5-choice="${i}"><span class="diag-option-letter">${'ABCD'[i]}</span><span>${laV5Safe(op.text)}</span><span class="diag-option-radio"></span></button>`).join('')}</div><div class="diag-quiz-nav"><button type="button" class="diag-back" data-v5-prev ${laV5State.index===0?'disabled':''}>← Ortga</button><span>Istalgan savolga qaytishingiz mumkin</span><button type="button" class="diag-primary" data-v5-next>${laV5State.index===14?'Natijani hisoblash':'Keyingi savol →'}</button></div></div>`}
 const scored=laV5State.items.map((q,i)=>({q,choice:laV5State.answers[i],correct:Number.isInteger(laV5State.answers[i])&&q.choices[laV5State.answers[i]].correct}));const count=scored.filter(s=>s.correct).length,answered=scored.filter(s=>Number.isInteger(s.choice)).length,rep=laV5ResultLabel(count);return `<div class="diag-head"><span class="diag-brand">✦ LEARNERS AREA / RESULT</span><span class="diag-num">3 / 3 · Yakuniy tahlil</span></div><div class="diag-body"><div class="diag-result"><div><div class="diag-eyebrow">${laV5Safe(laV5State.level)} · DIAGNOSTIKA NATIJASI</div><h3>${laV5Safe(rep.label)}</h3><p class="diag-muted">${laV5Safe(rep.note)}</p></div><div class="diag-score"><b>${count}<small>/15</small></b><span>${laV5Percent(count,15)}%</span></div></div><div class="diag-skill-results">${LA_V5_SKILLS.map(([k,t])=>{const arr=scored.filter(r=>r.q.skill===k);const c=arr.filter(r=>r.correct).length;return `<div><span>${t}</span><b>${c}/3</b><i><em style="width:${laV5Percent(c,3)}%"></em></i></div>`}).join('')}</div><p class="diag-interpretation">${answered<15?(landingLocale()==='en'?`${15-answered} questions were unanswered and counted incorrect. `:`${15-answered} ta savol javobsiz qolgan va noto‘g‘ri deb hisoblangan. `):''}${landingLocale()==='en'?'This 15-question sample does not certify an official CEFR or IELTS level. Speaking and writing require separate assessment.':'Bu 15 savollik namunaviy diagnostika, rasmiy CEFR yoki IELTS darajasini tasdiqlamaydi. Speaking va Writing alohida baholanishi kerak.'}</p><details class="diag-review"><summary>Barcha savollar va javoblar izohini ko‘rish <span>+</span></summary><div class="diag-review-list">${scored.map((s,i)=>{const correct=s.q.choices.find(o=>o.correct).text,selected=Number.isInteger(s.choice)?s.q.choices[s.choice].text:'Javob berilmagan';return `<details class="diag-review-item"><summary><span class="${s.correct?'good':'bad'}">${s.correct?'✓':'×'}</span><strong>${i+1}. ${laV5Safe(s.q.q)}</strong></summary><div><p>Sizning javobingiz: <b>${laV5Safe(selected)}</b></p><p>To‘g‘ri javob: <b>${laV5Safe(correct)}</b></p><p>${laV5Safe(s.q.explanation||'Javobni matn va kontekst bilan solishtiring.')}</p>${s.q.skill==='listening'?`<p><b>Audio matni:</b> ${laV5Safe(s.q.audio)}</p>`:''}</div></details>`}).join('')}</div></details><div class="diag-goal"><strong>IELTS bo‘yicha maqsadingiz</strong><div>${['6.5','7.0','8.0'].map(x=>`<button type="button" data-v5-goal="${x}" class="${laV5State.goal===x?'selected':''}">${x}</button>`).join('')}</div><small id="diag-goal-hint">${landingLocale()==='en'?`IELTS goal: ${laV5State.goal}. Keep practising regularly and reviewing your skills, whatever the result.`:`Maqsad: IELTS ${laV5State.goal}. Natijadan qat’i nazar, muntazam mashq va ko‘nikmalar tahlili bilan ishlang.`}</small></div><div class="diag-final-actions"><button class="diag-primary" type="button" data-v5-retake>Yangi 15 savolni ishlash ↻</button><button class="diag-back" type="button" data-v5-rechoose>Darajani almashtirish</button><a href="#/login" class="diag-entry">Platformaga kirish ↗</a></div></div>`}
function laV5Refresh(){const el=document.getElementById('challenge-widget');if(el){el.innerHTML=laV5View();el.setAttribute('aria-live','off');translateLanding(el,landingLocale())}}
function laV5Stop(){if(laV5Audio){laV5Audio.pause();laV5Audio.currentTime=0;laV5Audio=null}if('speechSynthesis' in window){speechSynthesis.cancel()}laV5Speech=null;const n=document.getElementById('diag-audio-note');if(n&&n.textContent.includes('tinglanmoqda'))n.textContent='Tinglash yakunlandi.'}
function laV5Say(){const q=laV5Selected();if(q?.skill!=='listening')return;laV5Stop();const note=document.getElementById('diag-audio-note'),attached=laV5AudioUrls.get(q.id);
 if(attached){try{laV5Audio=new Audio(attached);laV5Audio.playbackRate=1;laV5Audio.onended=()=>{if(note)note.textContent='Yozuv tugadi. Qayta tinglashingiz mumkin.'};laV5Audio.play().catch(()=>{if(note)note.textContent='Audio ijro etilmadi. Faylni qayta tanlang.'});if(note)note.textContent='Siz ulagan audio yozuvi tinglanmoqda.';return}catch{}}
 if(!('speechSynthesis' in window)){if(note)note.textContent='Ushbu brauzerda ovoz xizmati mavjud emas. Mos MP3 yuklang.';return}
 const voices=speechSynthesis.getVoices(), english=voices.filter(v=>/^en[-_]/i.test(v.lang));const priority=['Ava','Samantha','Daniel','Serena','Karen','Moira','Google UK English Female','Microsoft Aria','Microsoft Jenny','Google US English'];const score=v=>{const s=v.name||'';let x=english.includes(v)?100:0;priority.forEach((k,i)=>{if(s.toLowerCase().includes(k.toLowerCase()))x+=100-i*3});if(/natural|enhanced|premium/i.test(s))x+=35;return x};english.sort((a,b)=>score(b)-score(a));const utter=new SpeechSynthesisUtterance(q.audio);if(english[0])utter.voice=english[0];utter.lang=utter.voice?.lang||'en-GB';utter.rate=0.94;utter.pitch=1;utter.volume=1;utter.onend=()=>{if(note)note.textContent='Tinglash yakunlandi.'};utter.onerror=()=>{if(note)note.textContent='Brauzer ovozi ishlamadi. Mos audio fayl yuklash mumkin.'};laV5Speech=utter;speechSynthesis.speak(utter);if(note)note.textContent='Qurilmangizdagi inglizcha ovoz tinglanmoqda. Ovoz sifati tizim sozlamasiga bog‘liq.'}
function laV5Start(){laV5Stop();laV5State.items=laV5MakeSet(laV5State.level);laV5State.answers=Array(15).fill(null);laV5State.index=0;laV5State.mode='quiz';laV5State.startedAt=Date.now();laV5Refresh()}
function laV5Next(){laV5Stop();if(laV5State.index===14){laV5State.mode='result'}else laV5State.index++;laV5Refresh()}
function laV5PublicEvents(e){const t=e.target.closest('[data-v5-level],[data-v5-start],[data-v5-choice],[data-v5-next],[data-v5-prev],[data-v5-jump],[data-v5-retake],[data-v5-rechoose],[data-v5-play],[data-v5-stop],[data-v5-goal],[data-v5-motion]');if(!t)return;e.preventDefault();if(t.hasAttribute('data-v5-level')){laV5State.level=t.dataset.v5Level;laV5Refresh()}
 else if(t.hasAttribute('data-v5-start')||t.hasAttribute('data-v5-retake'))laV5Start();
 else if(t.hasAttribute('data-v5-rechoose')){laV5Stop();laV5State.mode='select';laV5Refresh()}
 else if(t.hasAttribute('data-v5-choice')){laV5State.answers[laV5State.index]=Number(t.dataset.v5Choice);laV5Refresh()}
 else if(t.hasAttribute('data-v5-prev')){laV5Stop();laV5State.index=Math.max(0,laV5State.index-1);laV5Refresh()}
 else if(t.hasAttribute('data-v5-next'))laV5Next();
 else if(t.hasAttribute('data-v5-jump')){laV5Stop();laV5State.index=Number(t.dataset.v5Jump);laV5Refresh()}
 else if(t.hasAttribute('data-v5-play'))laV5Say();else if(t.hasAttribute('data-v5-stop'))laV5Stop();
 else if(t.hasAttribute('data-v5-goal')){laV5State.goal=t.dataset.v5Goal;laV5Refresh()}
 
}
