function methodPublic(){return `${publicNav('/method')}<main><section class="container public-section"><span class="eyebrow">LEARNING METHOD</span><h1 style="max-width:800px">Kamroq chalg‘ish. Ko‘proq <span class="gradient-text">mazmunli mashq.</span></h1><p class="muted" style="max-width:690px">Har bir mashg‘ulot aniq natija bilan yakunlanadi: yechilgan savollar, yozilgan ish, qayta ko‘riladigan xatolar yoki o‘zlashtirilgan so‘zlar.</p><div class="grid cols2 top-space"><div class="card" style="padding:34px"><div class="icon-wrap">${icon('target')}</div><h3 class="top-space">Aniq maqsad</h3><p class="muted">Har hafta asosiy prioritetlarni belgilang. Ko‘nikmalar bo‘yicha bo‘shliqlarni aniqlang.</p></div><div class="card" style="padding:34px"><div class="icon-wrap green">${icon('rotate')}</div><h3 class="top-space">Practice → Feedback → Repeat</h3><p class="muted">Faol mashq, feedback va maqsadli takrorlash tizimli o‘sish uchun asos bo‘ladi.</p></div><div class="card" style="padding:34px"><div class="icon-wrap amber">${icon('calendar')}</div><h3 class="top-space">Ritm</h3><p class="muted">Live class va assignmentlarni haftalik tartibga joylang.</p></div><div class="card" style="padding:34px"><div class="icon-wrap">${icon('chart')}</div><h3 class="top-space">Natijalar dinamikasi</h3><p class="muted">Mock va individual faoliyat ko‘rsatkichlarini oldingi davrlar bilan solishtiring.</p></div></div></section></main>${publicFooter()}`}
function aboutPublic(){return `${publicNav('/about')}<main><section class="container public-section"><div class="eyebrow">ABOUT LEARNERS AREA</div><h1 style="max-width:850px">Ingliz tilini o‘rganish uchun <span class="gradient-text">aniq va zamonaviy</span> makon.</h1><p style="max-width:750px;font-size:17px;color:#69778f">Learners Area — IELTSga tayyorgarlik, o‘quvchilar, o‘qituvchilar va kurs boshqaruvi uchun yaratilayotgan onlayn ta’lim platformasi. Platformamizdagi imkoniyatlar bilan tanishing.</p><div class="grid cols3 top-space">${cardInfo('book','O‘quvchi','Barcha ko‘nikmalar bitta boshqaruv panelida.')}${cardInfo('users','O‘qituvchi','O‘ziga biriktirilgan o‘quvchilar uchun vazifalar va sessiyalar.')}${cardInfo('shield','Boshqaruv','Role-based nazorat, kontent va tizimni boshqarish.')}</div></section></main>${publicFooter()}`}
function faqPublic(){const data=[['Learners Area saytida qanday imkoniyatlar mavjud?',"Bu IELTS va ingliz tili ko‘nikmalari uchun darslar, testlar, topshiriqlar va progressni birlashtiruvchi platforma. Unda siz har bir ko'nikma ustida aloxida ishlaysiz va tizimli ravishda rivojlanasiz. Natijalaringizni kuzatib borishingiz mumkin."],['Platformaga qanday kiraman?','Havfsizlik tizimi sababli hozir faqat Telegram orqali autentifikatsiyadan o‘tib kirishingiz mumkin.']];return `${publicNav('/faq')}<main><section class="container public-section" style="max-width:1000px"><span class="eyebrow">HELP CENTER</span><h1>Ko‘p beriladigan savollar</h1>${data.map((x,i)=>`<details class="card flat" style="margin-top:11px"><summary style="font-weight:740;cursor:pointer">${esc(x[0])}</summary><p class="muted" style="margin:15px 0 0">${esc(x[1])}</p></details>`).join('')}</section></main>${publicFooter()}`}
function contactPublic(){return `${publicNav('')}<main><section class="container public-section" style="max-width:900px"><span class="eyebrow">CONTACT</span><h1>Biz bilan bog‘lanish</h1><p class="muted">Savol va takliflaringizni rasmiy Telegram orqali yuboring.</p><p class="top-space"><a class="premium-action premium-action-gold" href="https://t.me/Learnersareaaccessbot" target="_blank" rel="noopener noreferrer">Telegram botga o‘tish ${icon('external','sm')}</a></p></section></main>${publicFooter()}`}
function privacyPublic(){return `${publicNav('')}<main><section class="container public-section" style="max-width:900px"><span class="eyebrow">PRIVACY</span><h1>Maxfiylik va ma’lumotlardan foydalanish</h1><div class="card"><h3>Ochiq diagnostika qanday ishlaydi?</h3><p class="muted">Ochiq diagnostika savollari brauzerda bajariladi; haqiqiy shaxsiy hisob ma’lumotlari faqat server orqali avtorizatsiya qilingandan so‘ng ko‘rsatiladi.</p><h3>Mahalliy saqlash</h3><p class="muted">Ushbu ochiq sinov javoblari mahalliy hisoblanadi. Yopiq o‘quv ma’lumotlari himoyalangan server interfeysidan keladi.</p><h3>Real platforma</h3><p class="muted">Kirish va shaxsiy ma’lumotlarga ruxsat server tomonidan tekshiriladi.</p></div></section></main>${publicFooter()}`}

function publicHTML(path){
 const html=path==='/method'?methodPublic():path==='/about'?aboutPublic():path==='/faq'?faqPublic():path==='/contact'?contactPublic():path==='/privacy'?privacyPublic():homePublic();
 return html.replace(/href="#\/(.*?)"/g,(_,dest)=>'href="/'+(dest||'landing')+'"').replaceAll('https://learnersarea.uz/brand/welcome-landscape.jpg','/brand/welcome-landscape.jpg');
}
import {entryDestination} from '../js/session.js';
const heroSlides=[['Keep moving forward.','Har bir mashq — maqsadga yaqinroq.'],['Read with clarity.','Matndan asosiy ma’lumotni tezroq ajrating.'],['Write with purpose.','Yozganingizni qayta tahlil qilishga odatlaning.'],['Speak with confidence.','Javoblaringizni mashq qilib rivojlantiring.']];
export async function mount({root,signal,url}){
 const style=document.createElement('link');style.rel='stylesheet';style.href='/modules/premium-landing.css';style.dataset.premiumStyles='';document.head.append(style);
 const holder=document.createElement('div');holder.className='public la-premium-public';holder.innerHTML=publicHTML(url?.pathname||location.pathname);root.append(holder);translateLanding(holder,landingLocale());
 entryDestination(signal).then(route=>{if(!signal.aborted){for(const a of holder.querySelectorAll('[data-public-dashboard]'))a.href=route==='/app'?'/app/dashboard':'/login';}}).catch(()=>{});
 document.documentElement.dataset.v5MotionState='running';
 let timer=null,observer=null;
 const heading=holder.querySelector('#hero-dynamic-heading');
 if(heading){let i=0;timer=setInterval(()=>{if(signal.aborted||document.hidden||document.documentElement.dataset.v5MotionState==='paused')return;i=(i+1)%heroSlides.length;heading.textContent=heroSlides[i][0];const d=holder.querySelector('#hero-dynamic-desc');if(d)d.textContent=heroSlides[i][1];if(d)translateLanding(d,landingLocale());holder.querySelectorAll('#hero-progress-steps b').forEach((n,j)=>n.classList.toggle('current',i===j));},3700);}
 const pic=holder.querySelector('.cinema-original-picture');if(pic){const ready=()=>pic.classList.add('picture-ready');if(pic.complete&&pic.naturalWidth)ready();else pic.addEventListener('load',ready,{once:true,signal});}
 const revealed=[...holder.querySelectorAll('[data-reveal]')];if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.07});revealed.forEach(el=>observer.observe(el));}else revealed.forEach(el=>el.classList.add('is-visible'));
 function click(e){
  const language=e.target.closest('[data-public-locale]');if(language){e.preventDefault();const next=language.dataset.publicLocale;storeLandingLocale(next);translateLanding(holder,next);return;}
  const menu=e.target.closest('[data-public-menu]');if(menu){e.preventDefault();e.stopPropagation();const links=holder.querySelector('#premium-nav-links');const on=links?.classList.toggle('is-open');menu.setAttribute('aria-expanded',String(on));return;}
  const quiz=e.target.closest('[data-v5-level],[data-v5-start],[data-v5-choice],[data-v5-next],[data-v5-prev],[data-v5-jump],[data-v5-retake],[data-v5-rechoose],[data-v5-play],[data-v5-stop],[data-v5-goal],[data-v5-motion]');if(quiz){laV5PublicEvents(e);return;}
  const tab=e.target.closest('[data-public-tab]');if(tab){e.preventDefault();const id=tab.dataset.publicTab;if(!PREMIUM_SKILLS[id])return;holder.querySelector('#explorer-display').innerHTML=skillPreview(id).replace(/href="#\/(.*?)"/g,(_,dest)=>'href="/'+dest+'"');translateLanding(holder.querySelector('#explorer-display'),landingLocale());holder.querySelectorAll('[data-public-tab]').forEach(t=>{const active=t===tab;t.classList.toggle('active',active);t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1;});const foot=holder.querySelector('.explorer-sidebar-foot span:last-child');if(foot)foot.textContent=PREMIUM_SKILLS[id].code+' / 04';return;}
  const jump=e.target.closest('[data-scroll]');if(jump){const el=holder.querySelector('#'+jump.dataset.scroll);if(el){e.preventDefault();el.scrollIntoView({behavior:'smooth',block:'start'});}return;}
  if(e.target.closest('.premium-nav-links a')){holder.querySelector('#premium-nav-links')?.classList.remove('is-open');holder.querySelector('[data-public-menu]')?.setAttribute('aria-expanded','false');}
 }
 function keydown(e){const tab=e.target.closest('[data-public-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...holder.querySelectorAll('[data-public-tab]')];const at=tabs.indexOf(tab),i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(at+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i]?.click();tabs[i]?.focus();}
 function upload(e){const input=e.target.closest('[data-v5-upload]');if(!input)return;const f=input.files?.[0],q=laV5Selected();if(!f||!q||q.skill!=='listening'||!f.type.startsWith('audio/'))return;laV5Stop();const old=laV5AudioUrls.get(q.id);if(old)URL.revokeObjectURL(old);laV5AudioUrls.set(q.id,URL.createObjectURL(f));const n=holder.querySelector('#diag-audio-note');if(n)n.textContent='Audio fayl tanlandi. Play tugmasini bosing.';}
 function scroll(){const h=holder.querySelector('[data-premium-header]');if(h)h.classList.toggle('is-scrolled',window.scrollY>40);}
 holder.addEventListener('click',click,{signal});holder.addEventListener('keydown',keydown,{signal});holder.addEventListener('change',upload,{signal});window.addEventListener('scroll',scroll,{signal,passive:true});scroll();
 signal.addEventListener('abort',()=>{if(timer)clearInterval(timer);observer?.disconnect();laV5Stop();for(const u of laV5AudioUrls.values())URL.revokeObjectURL(u);laV5AudioUrls.clear();style.remove();holder.remove();delete document.documentElement.dataset.v5MotionState;},{once:true});
}
